@pytest_asyncio.fixture
async def observation_result(projection, monkeypatch):
    h = projection
    h.settings.database.postgres_memory_table = h.prefix + "_observations"
    h.memories = PostgresVectorMemoryStore(h.settings)
    await h.memories.initialize()
    h.sessions._memory_runtime_service = MemoryRuntimeService(h.memories)
    h.sessions._observation_runtime_service = ObservationRuntimeService()
    execute = h.runtime.execute_turn
    async def execute_with_tools(*args, **kwargs):
        result = await execute(*args, **kwargs)
        result.state["tool_results"] = [{"tool_key": "fixture-reader", "status": "completed",
            "call_id": key, "job_id": "fixture-job-" + key, "summary": "original " + key,
            "output": {"text": "original " + key}} for key in ("A", "B")]
        return result

    h.result_values = {}
    async def pause(**kwargs):
        h.result_values.update(kwargs)
        raise ConnectionError("injected pause after observation result freeze")

    h.task = await selected(h)
    with monkeypatch.context() as patch:
        patch.setattr(h.runtime, "execute_turn", execute_with_tools)
        patch.setattr(h.sessions, "_finalize_runtime_result", pause)
        with pytest.raises(ConnectionError, match="observation result freeze"):
            await run(h, h.task)
    h.asset = await FrameworkRuntimeResults(h.tasks).load(h.task.runtime_owner)
    try:
        yield h
    finally:
        with postgres_connect(h.settings) as conn, conn.cursor() as cur:
            cur.execute(f"DROP TABLE {h.settings.database.postgres_memory_table}")


def memory_rows(h):
    with postgres_connect(h.settings) as conn, conn.cursor() as cur:
        cur.execute(f"SELECT *, embedding::text AS embedding FROM {h.settings.database.postgres_memory_table} "
            "WHERE kind='observation' AND session_id=%s ORDER BY id", (h.session_id,))
        return [dict(row) for row in cur.fetchall()]


@pytest.mark.asyncio
async def test_retry_reuses_original_observations_and_actual_rows(observation_result, monkeypatch):
    h = observation_result
    await stop_after_snapshot(h, monkeypatch)
    original = memory_rows(h)
    assert len(original) == 2
    await stop_after_snapshot(h, monkeypatch)
    assert memory_rows(h) == original
    assert h.native_runs == 1 and len(h.runtime.calls) == 1
    assert len([event for event in await h.store.list_events(h.session_id) if event.type == "observations.persisted"]) == 1


async def original_observations(h):
    saved = await stage(h, h.task)
    return FrameworkObservationAsset.model_validate(saved.source_manifest[ASSET_KEY])


async def prepare_without_memory_writes(h, monkeypatch):
    async def pause(*args, **kwargs):
        raise ConnectionError("injected pause before observation rows")
    with monkeypatch.context() as patch:
        patch.setattr(h.sessions._memory_runtime_service, "write_observations", pause)
        with framework_owner_scope(h.task.runtime_owner):
            with pytest.raises(ConnectionError, match="before observation rows"):
                await h.sessions._finalize_runtime_result(**h.result_values)
    return await original_observations(h)


@pytest.mark.asyncio
async def test_retry_uses_frozen_preparation_not_current_builders(observation_result, monkeypatch):
    h = observation_result
    await stop_after_snapshot(h, monkeypatch)
    original = await original_observations(h)
    def forbidden(*args, **kwargs):
        raise AssertionError("Do not rebuild original observations or requests")
    monkeypatch.setattr(h.sessions._observation_runtime_service, "build_tool_observations", forbidden)
    monkeypatch.setattr(h.sessions._memory_runtime_service, "build_observation_requests", forbidden)
    await stop_after_snapshot(h, monkeypatch)
    assert await original_observations(h) == original
    assert {row["id"] for row in memory_rows(h)} == {item.id for item in original.observations}


@pytest.mark.asyncio
@pytest.mark.parametrize("changed", ["content", "metadata", "created_at", "updated_at", "embedding", "missing"])
async def test_changed_original_memory_row_is_not_overwritten(observation_result, monkeypatch, changed):
    h = observation_result
    await stop_after_snapshot(h, monkeypatch)
    identity = memory_rows(h)[0]["id"]
    with postgres_connect(h.settings) as conn, conn.cursor() as cur:
        if changed == "missing":
            cur.execute(f"DELETE FROM {h.settings.database.postgres_memory_table} WHERE id=%s", (identity,))
        else:
            expression = {"content": "'different content'", "metadata": "metadata || '{\"drift\":true}'::jsonb",
                "created_at": "created_at+interval '1 second'", "updated_at": "updated_at+interval '1 second'",
                "embedding": "'[1,2]'::vector"}[changed]
            cur.execute(f"UPDATE {h.settings.database.postgres_memory_table} SET {changed}={expression} WHERE id=%s", (identity,))
    actual = memory_rows(h)
    with framework_owner_scope(h.task.runtime_owner):
        with pytest.raises(FrameworkMessageStageRecoveryRequired, match="observation row"):
            await h.sessions._finalize_runtime_result(**h.result_values)
    assert memory_rows(h) == actual
    assert "application_projection_commit" not in (await stage(h, h.task)).source_manifest


