@pytest.mark.asyncio
async def test_partial_observation_batch_only_writes_missing_row(observation_result, monkeypatch):
    h = observation_result
    write = h.memories.write
    calls = []
    async def fail_second(request, **kwargs):
        calls.append(request.metadata["memory_id"])
        if len(calls) == 2:
            raise ConnectionError("injected second observation failure")
        return await write(request, **kwargs)
    with monkeypatch.context() as patch:
        patch.setattr(h.memories, "write", fail_second)
        with framework_owner_scope(h.task.runtime_owner):
            with pytest.raises(ConnectionError, match="second observation failure"):
                await h.sessions._finalize_runtime_result(**h.result_values)
    first, = memory_rows(h)
    assert len((await stage(h, h.task)).source_manifest[COMMITS_KEY]["row_hashes"]) == 1
    retry_calls = []
    async def record(request, **kwargs):
        retry_calls.append(request.metadata["memory_id"])
        return await write(request, **kwargs)
    monkeypatch.setattr(h.memories, "write", record)
    await stop_after_snapshot(h, monkeypatch)
    assert retry_calls == [calls[1]]
    assert first in memory_rows(h)
    assert len(memory_rows(h)) == 2


@pytest.mark.asyncio
async def test_successful_rows_skip_reembedding_and_vector_republication(observation_result, monkeypatch):
    h = observation_result
    embeddings, vectors = [], []
    class Embeddings:
        async def embed_texts(self, texts):
            embeddings.append(list(texts))
            return SimpleNamespace(vectors=[[1., 0.] for _ in texts], model_name="fixture", provider="fixture",
                adapter="fixture", original_dimension=2, stored_dimension=2, embedding_version="fixture-v1", normalized=True)
    class Vectors:
        async def create_index(self, **kwargs):
            pass
        async def upsert(self, **kwargs):
            vectors.append(kwargs)
    h.sessions._memory_runtime_service._embedding_runtime_service = Embeddings()
    h.sessions._memory_runtime_service.set_vector_store(Vectors())
    await stop_after_snapshot(h, monkeypatch)
    original = memory_rows(h)
    assert len(embeddings) == 1 and len(vectors) == 2
    await stop_after_snapshot(h, monkeypatch)
    assert len(embeddings) == 1 and len(vectors) == 2
    assert memory_rows(h) == original


@pytest.mark.asyncio
async def test_final_transaction_rechecks_observation_rows(observation_result, monkeypatch):
    h = observation_result
