@pytest.mark.asyncio
@pytest.mark.parametrize("changed", ["asset", "receipt", "format"])
async def test_inconsistent_observation_journal_requires_reconciliation(observation_result, monkeypatch, changed):
    h = observation_result
    await stop_after_snapshot(h, monkeypatch)
    record = (await stage(h, h.task)).model_dump(mode="json")
    if changed == "asset":
        record["source_manifest"][ASSET_KEY]["observations"][0]["summary"] = "changed original"
    elif changed == "receipt":
        record["source_manifest"][COMMITS_KEY]["row_hashes"] = {}
    else:
        record["schema_version"] = 9
    record["source_sha256"] = approval_value_hash(record["source_manifest"])
    with postgres_connect(h.settings) as conn, conn.cursor() as cur:
        cur.execute(f"UPDATE {message_stage_table(h.settings)} SET record=%s::jsonb WHERE task_id=%s",
            (json.dumps(record), h.task.id))
    from pydantic import ValidationError
    with framework_owner_scope(h.task.runtime_owner):
        with pytest.raises((FrameworkMessageStageRecoveryRequired, ValidationError)):
            await h.sessions._finalize_runtime_result(**h.result_values)
    assert len((await h.store.get_session(h.session_id)).messages) == 1


