@pytest.mark.asyncio
async def test_row_appearing_after_write_check_is_not_overwritten(observation_result, monkeypatch):
    import src.runtime.framework_observation_projection as commits

    h = observation_result
    await prepare_without_memory_writes(h, monkeypatch)
    prepare, write = commits.prepare_memory_projection, h.memories.write
    during_write = False
    def collide(cur, settings, projection, request):
        result = prepare(cur, settings, projection, request)
        if during_write and result[-1] is None:
            cur.execute(f"INSERT INTO {settings.database.postgres_memory_table} "
                "(id,scope,kind,content,created_at,updated_at) "
                "VALUES (%s,'session','observation','foreign',clock_timestamp(),clock_timestamp())",
                (request.metadata["memory_id"],))
        return result
    async def writing(*args, **kwargs):
        nonlocal during_write
        during_write = True
        try:
            return await write(*args, **kwargs)
        finally:
            during_write = False
    monkeypatch.setattr(commits, "prepare_memory_projection", collide)
    monkeypatch.setattr(h.memories, "write", writing)
    with framework_owner_scope(h.task.runtime_owner):
        with pytest.raises(FrameworkMessageStageRecoveryRequired, match="appeared after original intent"):
            await h.sessions._finalize_runtime_result(**h.result_values)
    assert memory_rows(h) == []


